import React from "react";

import "./Board.css";

const Board = () => {
    const squares = [1, 2, 3, 4, 5, 6, 7, 8, 9];

    return (
        <div className='board'>
            {squares.map((square) => (
                <div key={square} className='square'>
                    {square}
                </div>
            ))}
        </div>
    );
};

export default Board;
